INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35211, 'Titus 2:2', 'Titus', 2, 2, 'سپین‌ږیرو ته ووایه چې هغوی دې هوښیار او عزتمن وي، په خپلو نفسونو باندې واک ولري، په ایمان، مینه، صبر او زغم کې ټینګ اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_2.mp3', '', 1761754199, 1761754199),
(35212, 'Titus 2:3', 'Titus', 2, 3, 'همدارنګه سپین سرو ته ووایه چې په خپل چال چلند کې سپېڅلې اوسي، غیبت دې نه کوي او ډېر شراب دې نه څښي او نورو ته دې د نېکۍ کولو تعلیم ورکوي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_3.mp3', '', 1761754199, 1761754199),
(35213, 'Titus 2:4', 'Titus', 2, 4, 'ترڅو دوی وکولای شي هغو ځوانو ښځو ته داسې روزنه ورکړي چې د خپلو مېړونو او اولادونو سره مینه وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_4.mp3', '', 1761754199, 1761754199),
(35214, 'Titus 2:5', 'Titus', 2, 5, 'همدارنګه هغوی دې په خپلو نفسونو باندې واک ولري، پاک لمنې، په خپلو کورونو کې ښې کارکوونکې وي، مهربانې او د خپلو مېړونو تابعدارې اوسي، ترڅو د خدای کلام بدنام نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_5.mp3', '', 1761754199, 1761754199),
(35215, 'Titus 2:6', 'Titus', 2, 6, 'همدارنګه ځوانان وهڅوه چې اعتدال خوښوونکي اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_6.mp3', '', 1761754199, 1761754199),
(35216, 'Titus 2:7', 'Titus', 2, 7, 'تل باید داسې نېک کارونه وکړې چې د نورو دپاره مثال وګرځي او په خپل تعلیم کې دې ایمانداري او درنښت ښکاره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_7.mp3', '', 1761754199, 1761754199),
(35217, 'Titus 2:8', 'Titus', 2, 8, 'داسې سمې خبرې وکړه چې څوک درته ګوته ونه نیسي، ترڅو ستا مخالفین وشرمیږي او د هغوی سره به زمونږ په هکله د بدو ویلو دپاره کوم څه نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_8.mp3', '', 1761754199, 1761754199),
(35218, 'Titus 2:9', 'Titus', 2, 9, 'غلامانو ته ووایه چې په هر کار کې دې د خپلو بادارانو تابع اوسي او هغوی دې راضي ساتې او د هغوی سره دې بحث نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_9.mp3', '', 1761754199, 1761754199),
(35219, 'Titus 2:10', 'Titus', 2, 10, 'د هغوی څخه دې پیسې نه غلا کوي، بلکې خپله ټوله وفاداري دې وښایي، ترڅو په هره طریقه چې هغوی زمونږ د خلاصوونکي خدای په هکله کوم تعلیم ورکوي هغه په زړه پورې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_10.mp3', '', 1761754199, 1761754199),
(35220, 'Titus 2:11', 'Titus', 2, 11, 'ځکه چې د خدای فضل د ټولو خلکو د خلاصون دپاره ښکاره شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_11.mp3', '', 1761754199, 1761754199),
(35221, 'Titus 2:12', 'Titus', 2, 12, 'دا فضل مونږ ته رازده کوي چې بې‌مذهبي او دنیاوي غوښتنې پرېږدو او په دې دنیا کې د پرهېزګارۍ، عدالت او دیندارۍ ژوند وکړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_12.mp3', '', 1761754199, 1761754199),
(35222, 'Titus 2:13', 'Titus', 2, 13, 'نو مونږ د برکت نه ډکه هیله یعنې د خپل لوی خدای او خلاصوونکي عیسی مسیح د بېرته راتللو په انتظار یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_13.mp3', '', 1761754199, 1761754199),
(35223, 'Titus 2:14', 'Titus', 2, 14, 'هغه خپل ځان زمونږ په خاطر قربان کړ، ترڅو مونږ د هر ډول بدیو نه خلاص کړي او زمونږ څخه د خپل ځان دپاره داسې پاک قوم جوړ کړي چې د نېکو کارونو شوقیان اوسو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_14.mp3', '', 1761754199, 1761754199),
(35224, 'Titus 2:15', 'Titus', 2, 15, 'د دې شیانو په هکله تعلیم ورکړه او په پوره واک سره هغوی وهڅوه او اصلاح یې کړه. هېچا ته اجازه مه ورکوه چې تاته په سپکه سترګه وګوري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/titus2_verse_15.mp3', '', 1761754199, 1761754199),
(35225, 'Matthew 15:1', 'Matthew', 15, 1, 'وروسته ځینې فریسیان او د شریعت عالمان د اورشلیم څخه عیسی ته راغلل او د هغه څخه یې پوښتنه وکړه:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_1.mp3', '', 1761754199, 1761754199),
(35226, 'Matthew 15:2', 'Matthew', 15, 2, '«ستا شاګردان ولې زمونږ د نیکونو په رواجونو عمل نه کوي او د ډوډۍ خوړلو څخه مخکې خپل لاسونه نه وینځي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_2.mp3', '', 1761754199, 1761754199),
(35227, 'Matthew 15:3', 'Matthew', 15, 3, 'عیسی په ځواب کې وویل: «تاسو ولې د خپل رواج په خاطر د خدای حکم ماتوئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_3.mp3', '', 1761754199, 1761754199),
(35228, 'Matthew 15:4', 'Matthew', 15, 4, 'ځکه چې خدای حکم کړی دی: ‹د خپل مور او پلار عزت کوه او هرڅوک چې خپل مور او پلار ته ښکنځلې وکړي، باید ووژل شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_4.mp3', '', 1761754199, 1761754199),
(35229, 'Matthew 15:5', 'Matthew', 15, 5, 'خو تاسو وایئ، که چېرې څوک خپل مور او پلار ته ووایي چې زه تاسو سره مرسته نه شم کولای، ځکه هغه څه چې ما کولای شول تاسو ته یې درکړم، هغه مې خدای ته نذرانه کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_5.mp3', '', 1761754199, 1761754199),
(35230, 'Matthew 15:6', 'Matthew', 15, 6, 'نو هغه نور مجبور نه دی چې د خپل مور او پلار درناوی وکړي. په دې ډول تاسو د خپل دود او دستور په خاطر د خدای حکم بې‌ارزښته ګڼئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_6.mp3', '', 1761754199, 1761754199),
(35231, 'Matthew 15:7', 'Matthew', 15, 7, 'ای منافقانو، اشعیا نبي په حقه ؤ چې ستاسو په هکله یې پېشګویي وکړه چې خدای وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_7.mp3', '', 1761754199, 1761754199),
(35232, 'Matthew 15:8', 'Matthew', 15, 8, 'دا خلک په خوله زما عزت کوي، خو زړونه یې په بل ځای کې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_8.mp3', '', 1761754199, 1761754199),
(35233, 'Matthew 15:9', 'Matthew', 15, 9, 'د هغوی عبادت ګټه نه لري ځکه چې هغوی د خدای د حکمونو په ځای د انساني حکمونو تعلیم ورکوي.» هغه شیان چې انسان ناپاکه کوي (مرقوس ۷‏:‌۱۴‌‏-‌۲۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_9.mp3', '', 1761754199, 1761754199),
(35234, 'Matthew 15:10', 'Matthew', 15, 10, 'بیا عیسی خلک راوغوښتل او ورته ویې ویل: «زما خبرو ته غوږ ونیسئ او ځان ورباندې پوه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_10.mp3', '', 1761754199, 1761754199),
(35235, 'Matthew 15:11', 'Matthew', 15, 11, 'انسان چې څه خوري او څه څښي په هغو باندې نه ناپاکه کیږي، خو کومه خبره چې د هغه د خولې څخه راوځي په هغې ناپاکه کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_11.mp3', '', 1761754199, 1761754199),
(35236, 'Matthew 15:12', 'Matthew', 15, 12, 'بیا شاګردان عیسی ته راغلل او ورته ویې ویل: «ایا ته پوهېږې چې فریسیان ستا په خبرو خفه شول؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_12.mp3', '', 1761754199, 1761754199),
(35237, 'Matthew 15:13', 'Matthew', 15, 13, 'عیسی ځواب ورکړ: «هر نیالګی چې زمونږ اسماني پلار نه وي کرلی هغه به له بېخه وویستل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_13.mp3', '', 1761754199, 1761754199),
(35238, 'Matthew 15:14', 'Matthew', 15, 14, 'نو د هغوی پروا مه کوئ. دوی داسې ړانده دي چې نورو ړندو ته لاره ښایي. کله چې یو ړوند بل ړوند ته لاره ښایي، نو دواړه په کنده کې غورځیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_14.mp3', '', 1761754199, 1761754199),
(35239, 'Matthew 15:15', 'Matthew', 15, 15, 'بیا پطروس عیسی ته وویل: «مونږ ته د دې مثال معنی ووایه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_15.mp3', '', 1761754199, 1761754199),
(35240, 'Matthew 15:16', 'Matthew', 15, 16, 'عیسی پوښتنه وکړه: «ایا تاسو هم لا تر‌اوسه په دې شیانو نه پوهېږئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_16.mp3', '', 1761754199, 1761754199),
(35241, 'Matthew 15:17', 'Matthew', 15, 17, 'ایا تاسو نه پوهېږئ چې کوم شی چې خولې ته ننوځي هغه خېټې ته ځي او وروسته بیا د بدن څخه وځي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_17.mp3', '', 1761754199, 1761754199),
(35242, 'Matthew 15:18', 'Matthew', 15, 18, 'خو څه چې د خولې څخه راوځي هغه د زړه څخه راځي او په هغو باندې انسان ناپاکه کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_18.mp3', '', 1761754199, 1761754199),
(35243, 'Matthew 15:19', 'Matthew', 15, 19, 'ځکه چې خراب خیالونه، قتل، زناکاري، جنسي بد‌اخلاقي، غلا، د دروغو شهادت او تهمت د زړه نه راوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_19.mp3', '', 1761754199, 1761754199),
(35244, 'Matthew 15:20', 'Matthew', 15, 20, 'دا هغه شیان دي چې انسان ناپاکه کوي، خو په ناپاکو لاسونو باندې خوراک کول انسان نه ناپاکه کوي.» د یوې کنعانۍ ښځې ایمان (مرقوس ۷‏:‌۲۴‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_20.mp3', '', 1761754199, 1761754199),
(35245, 'Matthew 15:21', 'Matthew', 15, 21, 'بیا عیسی هغه ځای پرېښود او د صور او صیدون سیمو ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_21.mp3', '', 1761754199, 1761754199),
(35246, 'Matthew 15:22', 'Matthew', 15, 22, 'یوه کنعاني ښځه چې د هغه ځای اوسېدونکې وه هغه ته راغله او په چیغو چیغو یې ورته وویل: «ای ښاغلیه! ای د داود زویه! په ما باندې رحم وکړه. زما لور پېریانو نیولې ده او په سخت حالت کې ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_22.mp3', '', 1761754199, 1761754199),
(35247, 'Matthew 15:23', 'Matthew', 15, 23, 'خو عیسی ورته هېڅ ځواب ورنه کړ. شاګردان یې راغلل او زاري یې ورته وکړه او ویې ویل: «دا ښځه وشړه، ځکه چې هغه مونږ پسې چیغې وهي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_23.mp3', '', 1761754199, 1761754199),
(35248, 'Matthew 15:24', 'Matthew', 15, 24, 'بیا عیسی په ځواب کې وویل: «زه یوازې د اسراییلو د قوم د ورک شویو پسونو دپاره رالېږل شوی یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_24.mp3', '', 1761754199, 1761754199),
(35249, 'Matthew 15:25', 'Matthew', 15, 25, 'خو هغه ښځه راغله او د عیسی په پښو کې پرېوتله او ویې ویل: «ښاغلیه، زما سره مرسته وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_25.mp3', '', 1761754199, 1761754199),
(35250, 'Matthew 15:26', 'Matthew', 15, 26, 'عیسی په ځواب کې وویل: «دا سمه نه ده چې څوک دې د ماشوم ډوډۍ واخلي او سپیانو ته یې واچوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_26.mp3', '', 1761754199, 1761754199),
(35251, 'Matthew 15:27', 'Matthew', 15, 27, 'هغې ښځې وویل: «رښتیا ده ښاغلیه! خو سپي هم هغه پاتې شوې ډوډۍ خوري چې د خاوند د دسترخوان څخه یې وغورځیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_27.mp3', '', 1761754199, 1761754199),
(35252, 'Matthew 15:28', 'Matthew', 15, 28, 'بیا عیسی هغې ته په ځواب کې وویل: «ای ښځې، ستا ایمان ډېر قوي دی! څنګه چې ته غواړې هماغسې دې وشي.» او په هماغه ساعت د هغې لور روغه شوه. عیسی ډېرو خلکو ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_28.mp3', '', 1761754199, 1761754199),
(35253, 'Matthew 15:29', 'Matthew', 15, 29, 'عیسی د هغه ځای څخه روان شو او د جلیل د بحیرې په غاړه تېر شو او غره ته وخوت او هلته کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_29.mp3', '', 1761754199, 1761754199),
(35254, 'Matthew 15:30', 'Matthew', 15, 30, 'ډېر خلک ورته راغلل او ګوډان، ړانده، شلان، ګونګیان او نور ډېر ناروغان یې ورته راوستل او د هغه پښو ته به یې کښېنول او هغه به روغول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_30.mp3', '', 1761754199, 1761754199),
(35255, 'Matthew 15:31', 'Matthew', 15, 31, 'کله چې خلکو ولیدل چې ګونګیانو خبرې وکړلې، شلان ټول روغ شول، ګوډان وګرځېدل او ړانده بینا شول، نو حیران شول او د اسراییلو د خدای ثنا او صفت یې وکړ. عیسی څلور زره کسانو ته ډوډۍ ورکوي (مرقوس ۸‏:‌۱‌‏-‌۱۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_31.mp3', '', 1761754199, 1761754199),
(35256, 'Matthew 15:32', 'Matthew', 15, 32, 'عیسی خپل شاګردان راوغوښتل او ورته ویې ویل: «په دې خلکو باندې زما زړه سوځي، ځکه چې درې ورځې کیږي چې هغوی زما سره دي او هېڅ شی ورسره نشته چې ویې خوري. زه نه غواړم چې هغوی وږي رخصت کړم، هسې نه چې په لاره کې بې‌حاله شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_32.mp3', '', 1761754199, 1761754199),
(35257, 'Matthew 15:33', 'Matthew', 15, 33, 'شاګردانو په ځواب کې وویل: «په دې دښته کې دومره خلکو ته مونږ ډوډۍ له کومه کړو چې ماړه یې کړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_33.mp3', '', 1761754199, 1761754199),
(35258, 'Matthew 15:34', 'Matthew', 15, 34, 'عیسی هغوی ته وویل: «تاسو سره څو ډوډۍ دي؟» هغوی وویل: «اووه ډوډۍ او یو څو واړه ماهیان.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_34.mp3', '', 1761754199, 1761754199),
(35259, 'Matthew 15:35', 'Matthew', 15, 35, 'نو عیسی خلکو ته وویل چې په ځمکه کښېني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew15_verse_35.mp3', '', 1761754199, 1761754199),
